// Embeds the binary assets in ./assets as data URLs so that hosts
// need no asset-loader configuration. Run with `bun run embed-assets`.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dir, '..');

const assets = [
  { file: 'door.glb', mime: 'model/gltf-binary', name: 'doorModelUrl' },
  { file: 'nohemi-light.woff', mime: 'font/woff', name: 'floorTextFontUrl' }
];

const lines = [
  '// Generated by scripts/embed-assets.ts - do not edit.',
  ...assets.map(({ file, mime, name }) => {
    const data = readFileSync(join(root, 'assets', file)).toString('base64');
    return `export const ${name} = 'data:${mime};base64,${data}';`;
  })
];

writeFileSync(join(root, 'src/assets.generated.ts'), lines.join('\n') + '\n');
